function renderPresence(){if(!state.sheet)return;document.querySelectorAll('.cell.remote').forEach(e=>{e.classList.remove('remote','multi');e.style.removeProperty('--remote')});const remote=state.presence.filter(p=>p.sessionId!==state.sessionId),counts={};for(const p of state.presence)counts[p.userId]=(counts[p.userId]||0)+1;$('presence-count').textContent=Object.values(counts).reduce((a,b)=>a+b,0)+` view(s) open`;$('presence-legend').innerHTML=remote.map((p,i)=>{const color=colors[Math.abs(hash(p.sessionId))%colors.length];return `<span class="presence-chip"><i class="dot" style="background:${color}"></i>${escapeHtml(p.name)} · ${p.selection.start}${p.selection.end!==p.selection.start?':'+p.selection.end:''}</span>`}).join('');remote.forEach(p=>{const x=parseAddr(p.selection.start),y=parseAddr(p.selection.end),color=colors[Math.abs(hash(p.sessionId))%colors.length];if(!x||!y)return;for(let r=Math.min(x.r,y.r);r<=Math.max(x.r,y.r);r++)for(let c=Math.min(x.c,y.c);c<=Math.max(x.c,y.c);c++){const el=cellEl(r,c);if(el.classList.contains('remote'))el.classList.add('multi');el.classList.add('remote');el.style.setProperty('--remote',color)}})}
function hash(s){let h=0;for(const c of s)h=(h*31+c.charCodeAt(0))|0;return h}
function renderRevisions(){if(!state.revisions)return;$('revision-list').innerHTML=state.revisions.map(r=>`<div class="revision-item"><b>Revision ${r.revision}</b><br><small>${new Date(r.createdAt).toLocaleString()}</small><div class="revision-actions"><button data-preview="${r.revision}">Preview</button><button data-restore="${r.revision}">Restore as draft</button></div></div>`).join('')}
async function getRevision(n){const r=await fetch(`/api/workbooks/${state.workbook.id}/revisions/${n}`);if(!r.ok)throw new Error('Revision unavailable');return (await r.json()).content}
async function previewRevision(n){try{const w=await getRevision(n),before=state.workbook;state.workbook=w;state.sheet=w.sheets[0];render();message(`Previewing revision ${n}; select Restore to edit it`);setTimeout(()=>{state.workbook=before;state.sheet=before.sheets[0];render()},3500)}catch(e){message(e.message,true)}}
async function restoreRevision(n){try{const w=await getRevision(n),changes=[];const old=state.sheet.cells,neu=w.sheets[0].cells;for(const a of new Set([...Object.keys(old),...Object.keys(neu)]))if((old[a]||'')!==(neu[a]||''))changes.push({address:a,value:neu[a]||''});applyChanges(changes,`Restore revision ${n}`);message(`Revision ${n} loaded as an unsaved draft`)}catch(e){message(e.message,true)}}
async function updateHistoryMeta(){if(!state.workbook)return;const a=addr(state.sel.r2,state.sel.c2);try{const r=await fetch(`/api/workbooks/${state.workbook.id}/history?sheetId=${state.sheet.id}&address=${a}`),d=await r.json(),h=d.history?.[0];$('cell-meta').textContent=h?`Last changed by ${h.userName} · ${new Date(h.changedAt).toLocaleString()}`:'No saved edits yet'}catch{}}
async function showCellHistory(){const a=addr(state.sel.r2,state.sel.c2),r=await fetch(`/api/workbooks/${state.workbook.id}/history?sheetId=${state.sheet.id}&address=${a}`),d=await r.json();$('history-list').innerHTML=d.history.length?d.history.map(h=>`<div class="history-item"><b>${escapeHtml(h.userName)}</b> · rev ${h.revision}<br><small>${new Date(h.changedAt).toLocaleString()}</small><br>“${escapeHtml(h.oldValue)}” → “${escapeHtml(h.newValue)}”</div>`).join(''):'No saved changes for this cell.'}

function bind(){const grid=$('grid');grid.addEventListener('mousedown',e=>{const el=e.target.closest('.cell');if(!el)return;e.preventDefault();const r=+el.dataset.r,c=+el.dataset.c;if(state.editing&&$('editor').value.startsWith('=')){state.formulaPick=true;state.anchor={r,c};state.sel={r1:r,c1:c,r2:r,c2:c};insertFormulaRef(addr(r,c));return}state.dragging=true;if(e.shiftKey)select(r,c,true);else select(r,c)});grid.addEventListener('mouseover',e=>{if(!state.dragging&&!state.formulaPick)return;const el=e.target.closest('.cell');if(!el)return;state.sel.r2=+el.dataset.r;state.sel.c2=+el.dataset.c;if(state.formulaPick){const b=bounds();insertFormulaRef(b.r1===b.r2&&b.c1===b.c2?addr(b.r1,b.c1):`${addr(b.r1,b.c1)}:${addr(b.r2,b.c2)}`)}else render()});document.addEventListener('mouseup',()=>{if(state.dragging){state.dragging=false;sendPresence()}state.formulaPick=false});grid.addEventListener('dblclick',()=>startEdit());
 $('grid-wrap').addEventListener('keydown',e=>{const k=e.key,ctrl=e.ctrlKey||e.metaKey;if(ctrl&&k.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(ctrl&&k.toLowerCase()==='y'){e.preventDefault();redo();return}if(ctrl&&k.toLowerCase()==='c'){e.preventDefault();copy();return}if(ctrl&&k.toLowerCase()==='x'){e.preventDefault();copy(true);return}if(ctrl&&k.toLowerCase()==='v'){e.preventDefault();paste();return}if(k==='Delete'||k==='Backspace'){e.preventDefault();applyChanges(selectedChanges(()=>''),'Clear range');return}if(k==='F2'){e.preventDefault();startEdit();return}if(k.length===1&&!ctrl&&!e.altKey){e.preventDefault();startEdit(k);return}let dr=0,dc=0;if(k==='ArrowUp'||(k==='Enter'&&e.shiftKey))dr=-1;else if(k==='ArrowDown'||k==='Enter')dr=1;else if(k==='ArrowLeft'||(k==='Tab'&&e.shiftKey))dc=-1;else if(k==='ArrowRight'||k==='Tab')dc=1;else return;e.preventDefault();select(state.sel.r2+dr,state.sel.c2+dc,e.shiftKey&&k.startsWith('Arrow'))});
 $('editor').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();commitEdit(e.shiftKey?-1:1)}else if(e.key==='Tab'){e.preventDefault();const p=parseAddr($('editor').dataset.address);commitEdit();select(p.r,p.c+(e.shiftKey?-1:1))}else if(e.key==='Escape'){e.preventDefault();cancelEdit()}});$('editor').addEventListener('input',formulaAssist);$('editor').addEventListener('blur',()=>{if(state.editing&&!state.formulaPick)commitEdit()});$('suggestions').addEventListener('mousedown',e=>{e.preventDefault();const f=e.target.dataset.f;if(f){const ed=$('editor');ed.setRangeText(`${f}(`,ed.selectionStart-(ed.value.match(/[A-Za-z]*$/)?.[0].length||0),ed.selectionEnd,'end');formulaAssist()}});
 $('formula-bar').addEventListener('change',e=>applyChanges([{address:addr(state.sel.r2,state.sel.c2),value:e.target.value}],`Edit ${addr(state.sel.r2,state.sel.c2)}`));$('formula-bar').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.target.blur()}});$('undo').onclick=undo;$('redo').onclick=redo;$('save').onclick=save;$('fill-down').onclick=()=>fill('down');$('fill-right').onclick=()=>fill('right');$('go').onclick=()=>{const [a,z]=$('name-box').value.toUpperCase().split(':');selectRange(a,z)};$('name-box').addEventListener('keydown',e=>{if(e.key==='Enter')$('go').click()});$('find-next').onclick=findNext;$('replace-one').onclick=replaceOne;$('replace-all').onclick=replaceAll;$('history-toggle').onclick=()=>{$('side-panel').hidden=!$('side-panel').hidden;renderRevisions()};$('close-panel').onclick=()=>$('side-panel').hidden=true;$('cell-history').onclick=showCellHistory;$('revision-list').onclick=e=>{if(e.target.dataset.preview)previewRevision(+e.target.dataset.preview);if(e.target.dataset.restore)restoreRevision(+e.target.dataset.restore)};$('user').onchange=sendPresence;$('dismiss-conflict').onclick=()=>$('conflict-banner').hidden=true;document.addEventListener('paste',e=>{if(document.activeElement===$('grid-wrap')){e.preventDefault();pasteText(e.clipboardData.getData('text'))}})}
async function init(){buildGrid();bind();try{const r=await fetch('/api/bootstrap'),d=await r.json();if(!r.ok)throw new Error(d.error);state.workbook=d.workbook;state.sheet=d.workbook.sheets[0];state.users=d.users;state.revision=d.revision;state.revisions=d.revisions;$('title').textContent=d.workbook.title;$('user').innerHTML=d.users.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('');render();renderRevisions();connect();$('grid-wrap').focus()}catch(e){message(e.message,true)}}
